<?php $page_title='Appointments';require_once __DIR__.'/../includes/header.php';$rows=$pdo->query("SELECT a.*,p.name patient,d.name doctor FROM appointments a JOIN patients p ON p.id=a.patient_id JOIN doctors d ON d.id=a.doctor_id ORDER BY a.appointment_date DESC,a.appointment_time DESC")->fetchAll();?><div class="d-flex justify-content-between mb-3"><h2>Appointments</h2><a href="add.php" class="btn btn-primary">+ New Appointment</a></div><div class="card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Time</th><th>Patient</th><th>Doctor</th><th>Reason</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $a):?><tr><td><?=$a['appointment_date']?></td><td><?=$a['appointment_time']?></td><td><?=e($a['patient'])?></td><td><?=e($a['doctor'])?></td><td><?=e($a['reason'])?></td><td><?=$a['status']?></td></tr><?php endforeach;?></tbody></table></div></div><?php require_once __DIR__.'/../includes/footer.php';?>